{
    public void Configure(EntityTypeBuilder<SafetyInspection> builder)
    {
        builder.ToTable("safety_inspections", t =>
        {
            t.HasCheckConstraint("CK_safety_inspections_result", "[result] IN (N'pass', N'needs_action', N'fail')");
