        builder.Property(e => e.Result).HasColumnName("result").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'pass'");
        builder.Property(e => e.Notes).HasColumnName("notes").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.NextDue).HasColumnName("next_due").HasColumnType("date");
    }
}
